import{_ as a}from"./chunks/token-love-domain.DYwJFeu1.js";import{_ as t}from"./chunks/aliyun-hangzhou-2026-06-16-1.C_efC9m5.js";import{_ as r,o as n,c as i,a5 as o}from"./chunks/framework.bIR-4glx.js";const v=JSON.parse('{"title":"Author Projects and Real-world Practice","description":"A central disclosure of products, companies, and field work involving the author, including relationship, purpose, date, and non-sponsorship status.","frontmatter":{"title":"Author Projects and Real-world Practice","description":"A central disclosure of products, companies, and field work involving the author, including relationship, purpose, date, and non-sponsorship status.","updated":"2026-09-01T00:00:00.000Z"},"headers":[],"relativePath":"en/projects.md","filePath":"en/projects.md","lastUpdated":1788220800000}'),s={name:"en/projects.md"};function d(c,e,l,p,h,u){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="author-projects-and-real-world-practice" tabindex="-1">Author Projects and Real-world Practice <a class="header-anchor" href="#author-projects-and-real-world-practice" aria-label="Permalink to &quot;Author Projects and Real-world Practice&quot;">​</a></h1><p>This page centralises projects in which Han Xiankai has a direct role so that commercial relationships do not blend into learning-method recommendations. It is a disclosure, not a purchase, investment, or return promise.</p><p>To analyse a public experience mentioned here, use the <a href="./templates/ai-case-review">AI Case Review Template</a> to separate source, facts, judgment, and unknown outcomes first; project disclosure is not an independent audit.</p><h2 id="status-and-evidence-boundaries" tabindex="-1">Status and Evidence Boundaries <a class="header-anchor" href="#status-and-evidence-boundaries" aria-label="Permalink to &quot;Status and Evidence Boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th><th>How a reader should use it</th></tr></thead><tbody><tr><td><strong>Author affiliation</strong></td><td>The author has a stated role or material relationship with a company, product, or article</td><td>Treat it as self-disclosure, not an independent review</td></tr><tr><td><strong>In practice</strong></td><td>Work has begun, but impact, scale, or sustainability is still being tested</td><td>Look for samples, costs, user feedback, and failure records</td></tr><tr><td><strong>Historical material</strong></td><td>An older article, product page, or personal memory</td><td>Use it for context, not as current guidance</td></tr><tr><td><strong>Unverified</strong></td><td>A plan, goal, or judgment without enough public evidence</td><td>Wait for formal documents, agreements, users, and time</td></tr></tbody></table><p>Project status can change. Each item keeps its own checked date; a page update means the disclosure text was reorganised, not that a product result changed.</p><h2 id="china-token-cloud-and-token-love" tabindex="-1">China Token Cloud and token.love <a class="header-anchor" href="#china-token-cloud-and-token-love" aria-label="Permalink to &quot;China Token Cloud and token.love&quot;">​</a></h2><ul><li><strong>Relationship</strong>: Han Xiankai serves as chairman of China Token Cloud Computing Co., Ltd.</li><li><strong>Purpose</strong>: The current homepage describes <code>token.love</code> as a unified AI gateway for enterprise and government-related scenarios, listing model access, routing and failover, usage metering, audit trails, and private/offline deployment.</li><li><strong>Relationship to this guide</strong>: both are maintained by the same author; this is not third-party sponsorship.</li><li><strong>Checked</strong>: 2026-08-31. The capability list reflects the homepage checked that day; exact service and compliance scope must still be verified in the formal <a href="https://token.love/" target="_blank" rel="noreferrer">token.love</a> documentation, approvals, and contract.</li></ul><p><img src="'+a+'" alt="Archived token.love product page" loading="lazy" decoding="async" width="1736" height="730"></p><h2 id="ai-learning-project-development-and-resource-layer-entrepreneurship" tabindex="-1">AI Learning, Project Development, and Resource-layer Entrepreneurship <a class="header-anchor" href="#ai-learning-project-development-and-resource-layer-entrepreneurship" aria-label="Permalink to &quot;AI Learning, Project Development, and Resource-layer Entrepreneurship&quot;">​</a></h2><p>Han Xiankai is connecting personal AI learning, AI-assisted development, and China Token Cloud&#39;s enterprise-service practice into one working path: begin with a real task; use AI for requirements, prototypes, code, tests, documentation, and delivery; then organise multi-model access, routing, metering, permissions, deployment, and continuing operations into a resource-layer service a team can manage.</p><p>This path has a describable product and service direction. That does not mean profitability or scale has been publicly demonstrated. Customer retention, repeatable delivery, and whether revenue can cover model, infrastructure, engineering, support, acquisition, compliance, and incident costs still require evidence from real projects over time.</p><p>See <a href="./threads/part-3/2-ai-development-and-resource-layer">AI Learning, Project Development, and Resource-layer Entrepreneurship</a> for the method, business logic, cost boundaries, and twelve-week validation framework. It discusses possible charging models without disclosing or implying unverified revenue, profit, customer counts, or investment returns.</p><h2 id="wechat-articles-and-practice-notes" tabindex="-1">WeChat Articles and Practice Notes <a class="header-anchor" href="#wechat-articles-and-practice-notes" aria-label="Permalink to &quot;WeChat Articles and Practice Notes&quot;">​</a></h2><p>Public articles about the author provide observation and narrative material. They are not independent audits, customer case studies, or proof of commercial results:</p><ul><li><a href="https://mp.weixin.qq.com/s?src=11&amp;timestamp=1787503349&amp;ver=6922&amp;signature=hsfWcee*q*Okq4gsJ5TpMaWV4vZTwLean6SKtOxCC-EyAf9jWD6l1LQYDny29FqXVImHZFNFDPt*EVH*hVMN2pa91kZtuYfzI81wtV7yahnqVBsKS*c7Ls1uf9QqiEIF&amp;new=1" target="_blank" rel="noreferrer">“Han Xiankai: The Most ‘Abstract’ Human in AI”</a> (TokenMany, 11 August 2026) describes the author through a refusal of ready-made answers, cross-domain associations, and continued questioning. The project translates that into competing hypotheses, minimum experiments, and preserved failure evidence rather than treating a profile as a capability verdict.</li><li><a href="https://mp.weixin.qq.com/s?src=11&amp;timestamp=1787503349&amp;ver=6922&amp;signature=k7g1j*QF9lLWMGUlkAu65EFOmvokb8FoM51LNr4hgn4Q4Cc7q3t3O8Mkac7YnWTJbIVdvX-PXYdZXVHEohJieTOPR*Q2-TVAHuIg2ljgp2BMn8m7STrvovnpW01j817Y&amp;new=1" target="_blank" rel="noreferrer">“Han Xiankai and AI: Splitting the Noise into Emotion, Frame by Frame”</a> (Wanli Center, 21 August 2026) narrates a way to separate claims, evidence, emotional intensity, expression, and answerability in comments. The project borrows only the problem-decomposition frame and adds redaction, permission, retention, and human review; it does not present the story as validated public-opinion product performance.</li></ul><p>The links point to public WeChat pages and were checked on 24 August 2026; platform policy may make a signed link expire. The method and boundaries are documented in <a href="./threads/part-3/2-ai-development-and-resource-layer">AI Learning, Project Development, and Resource-layer Entrepreneurship</a>.</p><h2 id="ku0-com" tabindex="-1">ku0.com <a class="header-anchor" href="#ku0-com" aria-label="Permalink to &quot;ku0.com&quot;">​</a></h2><ul><li><strong>Relationship</strong>: the author participates in the operation and presentation of the project.</li><li><strong>Purpose</strong>: The current homepage describes it as an AI resource directory for mainland China businesses and developers, covering relay services, account recharge, asset transactions, model tools, and official references.</li><li><strong>Relationship to this guide</strong>: this is neither an independent review nor a recommendation without a material relationship.</li><li><strong>Checked</strong>: 2026-08-31. Categories and scope were checked against the homepage that day; availability, region, plans, transactions, and compliance statements must still be verified on <a href="https://ku0.com/" target="_blank" rel="noreferrer">ku0.com</a> and in written terms.</li></ul><h2 id="ai-and-physical-industry-practice" tabindex="-1">AI and Physical-industry Practice <a class="header-anchor" href="#ai-and-physical-industry-practice" aria-label="Permalink to &quot;AI and Physical-industry Practice&quot;">​</a></h2><p>On 16 June 2026, the author visited Alibaba Cloud&#39;s Hangzhou headquarters as a company representative and recorded plans to explore AI in agriculture and other physical industries, including free community training. This is a direction and personal commitment, not an Alibaba Cloud endorsement or evidence of completed outcomes.</p><p><img src="'+t+'" alt="Visit to Alibaba Cloud headquarters" loading="lazy" decoding="async" width="1080" height="1440"></p><h2 id="recommendation-policy" tabindex="-1">Recommendation Policy <a class="header-anchor" href="#recommendation-policy" aria-label="Permalink to &quot;Recommendation Policy&quot;">​</a></h2><p>Core chapters assess tools by task, evidence, privacy, and transfer. An affiliated product receives no higher evidence status and never replaces official documentation, independent comparison, or the reader&#39;s security review. Hidden sponsorship is not accepted. Any future paid relationship must identify the party, date, and affected scope next to the claim.</p><h2 id="verification-order" tabindex="-1">Verification Order <a class="header-anchor" href="#verification-order" aria-label="Permalink to &quot;Verification Order&quot;">​</a></h2><ol><li>Start with current formal documentation, contracts, licences, and applicable policy.</li><li>Ask how the result will be accepted, how cost is calculated, and how work stops on failure.</li><li>Treat personal narrative and public profiles as leads, not customer cases or proof of return.</li><li>For customer, identity, health, or commercial data, confirm permission, minimum necessary scope, and deletion method first.</li></ol>',26)])])}const b=r(s,[["render",d]]);export{v as __pageData,b as default};
